     * the terminal client reaches the captions of every available dub.
     */
    func captions(subjectId: String, resourceId: String, siblingIds: [String], season: UInt32, episode: UInt32) throws  -> [MobileSubtitle]
    
    func clearHistory() 
    
    /**
     * Full details, including the season/episode tree for series.
     */
    func details(subjectId: String) throws  -> MobileDetails
    
    /**
     * Favorites, newest last, mirroring the terminal client's ordering.
     */
    func favorites()  -> [MobileCatalogItem]
    
    /**
     * Watch history, most recent last.
     */
    func history()  -> [MobileHistoryItem]
    
    /**
     * One home/trending tab. Tab ids match the terminal client: `1`, `2`, `5`, `8`.
     */
    func home(tabId: String, page: UInt32) throws  -> [MobileCatalogItem]
    
    func isFavorite(subjectId: String, provider: String)  -> Bool
    
    /**
     * Persist playback progress. `completed` marks the episode watched.
     */
    func recordProgress(item: MobileHistoryItem, progressSeconds: UInt64, durationSeconds: UInt64?, completed: Bool) 
    
    /**
     * Stream candidates for a title. Movies use `season = 0, episode = 0`, which
     * is the same convention the terminal client uses.
     */
    func releases(subjectId: String, season: UInt32, episode: UInt32) throws  -> [MobileRelease]
    
    func removeFavorite(subjectId: String, provider: String) 
    
    func removeHistoryEntry(provider: String, subjectId: String, season: UInt32, episode: UInt32) 
    
    /**
     * Free-text search against the default provider.
     */
    func search(query: String, page: UInt32) throws  -> [MobileCatalogItem]
    
    /**
     * Online subtitles for a title, searched by the content being watched.
     *
     * Returns an empty list instead of failing: the picker still shows the
     * provider captions, so a missing internet connection never blocks playback.
     */
    func searchOnlineSubtitles(title: String, year: String?, isSeries: Bool, season: UInt32, episode: UInt32)  -> [MobileSubtitle]
    
    /**
     * Type-ahead suggestions for the search field.
     */
    func suggest(query: String) throws  -> [String]
    
    /**
     * Adds the item to favorites, or removes it if already present. Returns
     * `true` when the item ended up favorited.
     */
    func toggleFavorite(item: MobileCatalogItem)  -> Bool
    
}
